android.extraProguardRules:
# --- React Native / Hermes core ---
-keep class com.facebook.react.** { *; }
-keep class com.facebook.hermes.** { *; }
-keep class com.facebook.jni.** { *; }
-dontwarn com.facebook.react.**
-keepclasseswithmembernames class * { native <methods>; }
-keepclassmembers class * { @com.facebook.react.bridge.ReactMethod <methods>; }
-keepclassmembers class * { @com.facebook.react.uimanager.annotations.ReactProp <methods>; }
-keepclassmembers class * { @com.facebook.react.uimanager.annotations.ReactPropGroup <methods>; }

# --- Expo modules (resolved reflectively) ---
-keep class expo.modules.** { *; }
-dontwarn expo.modules.**

# --- Firebase ---
-keep class com.google.firebase.** { *; }
-dontwarn com.google.firebase.**

# --- Google Play services / AdMob / Play Core ---
-keep class com.google.android.gms.** { *; }
-dontwarn com.google.android.gms.**
-keep class com.google.android.play.** { *; }
-dontwarn com.google.android.play.**

# --- Appwrite + networking ---
-keep class io.appwrite.** { *; }
-dontwarn okhttp3.**
-dontwarn okio.**
-dontwarn kotlinx.coroutines.**

# --- Google Play Billing (react-native-iap) ---
-keep class com.android.billingclient.api.** { *; }
-dontwarn com.android.billingclient.api.**
-keep class com.android.vending.billing.** { *; }

# --- edge-to-edge ---
-keep class com.zoontek.rnedgetoedge.** { *; }

# --- Standard Android keeps ---
-keepclassmembers enum * { public static **[] values(); public static ** valueOf(java.lang.String); }
-keepclassmembers class * implements android.os.Parcelable { public static final android.os.Parcelable$Creator *; }
-keepattributes Signature,InnerClasses,EnclosingMethod,*Annotation*,SourceFile,LineNumberTable

# --- Android 15 edge-to-edge deprecations (Play vitals) ---
# Verified with dexdump on the shipped 1043 bundle: 7 live invoke sites for
# Window.setStatusBarColor. The callers are expo-image-picker's crop
# activity, expo-navigation-bar and androidx.activity's EdgeToEdge -- none
# of them our source, so withRNEdgeToEdgeFix (which patches react-android's
# own calls) cannot reach them and no -keep rule removes a reference.
# -assumenosideeffects makes R8 DELETE the invocations rather than rename
# them, which is what clears Play's static scan.
#
# Trade-off, stated plainly: on API 35+ (targetSdk is 36) these setters are
# already no-ops, so nothing changes. On API < 35 the system bars fall back
# to their default colour instead of a custom one -- cosmetic, Android 14
# and below.
#
# Verify after building: dexdump -d classes*.dex | grep -c
#   'Landroid/view/Window;.setStatusBarColor'   must be 0.
-assumenosideeffects class android.view.Window {
    public void setStatusBarColor(int);
    public void setNavigationBarColor(int);
    public int getStatusBarColor();
    public int getNavigationBarColor();
}
